# ── Method B: Per-task RSA (rsa_siglip_only.py style) ──

def compute_rsa_pertask(all_feats, all_actions):
    """Per-task method: compute RSA within each task, average across tasks."""
    rsa_values = []
    per_task = {}
    for task in TASKS:
        feats = all_feats.get(task, {})
        actions = all_actions.get(task, {})
        common = sorted(set(feats.keys()) & set(actions.keys()))
        if len(common) < 2:
            per_task[task] = None
            continue
        pairs = list(itertools.combinations(common, 2))
        rep_dists = [mean_cosine_distance_pertask(feats[a], feats[b]) for a, b in pairs]
        act_dists = [mean_action_distance(actions[a], actions[b]) for a, b in pairs]
        if np.std(rep_dists) < 1e-10 or np.std(act_dists) < 1e-10:
            per_task[task] = 0.0
            rsa_values.append(0.0)
            continue
        rsa, _ = spearmanr(rep_dists, act_dists)
        per_task[task] = float(rsa)
        rsa_values.append(float(rsa))

    if not rsa_values:
        return None, {}
    return float(np.mean(rsa_values)), per_task


# ── Method A: Cross-task + phase RSA (rsa_analysis.py style) ──

def compute_rsa_crosstask_phase(all_feats_flat, all_actions_flat):
    """Cross-task method: build full NxN RDM, split by phase, average phases."""
    sorted_keys = sorted(set(all_feats_flat.keys()) & set(all_actions_flat.keys()))
    N = len(sorted_keys)
    if N < 2:
        return None, {}

    phase_rsas = {}
    for phase in TEMPORAL_BINS:
        # Build representation RDM
        rep_dm = np.zeros((N, N), dtype=np.float32)
        act_dm = np.zeros((N, N), dtype=np.float32)

        phase_feat_cache = {}
        phase_act_cache = {}
        for idx, k in enumerate(sorted_keys):
            feat_arr = all_feats_flat[k]
            act_arr = all_actions_flat[k]
            feat_indices = get_temporal_indices(len(feat_arr), phase)
            act_indices = get_temporal_indices(len(act_arr), phase)
            if len(feat_indices) == 0:
                feat_indices = np.array([0])
            if len(act_indices) == 0:
                act_indices = np.array([0])
            phase_feat_cache[idx] = feat_arr[feat_indices]
            phase_act_cache[idx] = act_arr[act_indices]

        for i in range(N):
            for j in range(i + 1, N):
                rd = mean_cosine_distance_crosstask(phase_feat_cache[i], phase_feat_cache[j])
                ad = mean_cosine_distance_crosstask(phase_act_cache[i], phase_act_cache[j])
                rep_dm[i, j] = rd
                rep_dm[j, i] = rd
                act_dm[i, j] = ad
                act_dm[j, i] = ad

        tri_idx = np.triu_indices(N, k=1)
        r_vec = rep_dm[tri_idx]
        a_vec = act_dm[tri_idx]
        if np.std(r_vec) < 1e-10 or np.std(a_vec) < 1e-10:
            phase_rsas[phase] = 0.0
        else:
            rho, _ = spearmanr(r_vec, a_vec)
            phase_rsas[phase] = float(rho)

    mean_rsa = float(np.mean(list(phase_rsas.values())))
    return mean_rsa, phase_rsas


# ── Method C: Cross-task + full trajectory (hybrid) ──

def compute_rsa_crosstask_full(all_feats_flat, all_actions_flat):
    """Cross-task but no phase splitting - full trajectory."""
    sorted_keys = sorted(set(all_feats_flat.keys()) & set(all_actions_flat.keys()))
    N = len(sorted_keys)
    if N < 2:
        return None

    rep_dm = np.zeros((N, N), dtype=np.float32)
    act_dm = np.zeros((N, N), dtype=np.float32)

    for i in range(N):
        for j in range(i + 1, N):
            ki, kj = sorted_keys[i], sorted_keys[j]
            rd = mean_cosine_distance_pertask(all_feats_flat[ki], all_feats_flat[kj])
            ad = mean_action_distance(all_actions_flat[ki], all_actions_flat[kj])
            rep_dm[i, j] = rd
            rep_dm[j, i] = rd
            act_dm[i, j] = ad
            act_dm[j, i] = ad

    tri_idx = np.triu_indices(N, k=1)
    r_vec = rep_dm[tri_idx]
    a_vec = act_dm[tri_idx]
    if np.std(r_vec) < 1e-10 or np.std(a_vec) < 1e-10:
        return 0.0
    rho, _ = spearmanr(r_vec, a_vec)
    return float(rho)


def bootstrap_ci(values, n_boot=1000, ci=0.95):
    values = np.array(values)
    boot_means = [np.mean(np.random.choice(values, len(values), replace=True))
                  for _ in range(n_boot)]
    lo = np.percentile(boot_means, (1 - ci) / 2 * 100)
    hi = np.percentile(boot_means, (1 + ci) / 2 * 100)
    return float(np.mean(values)), float(lo), float(hi)


